import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import request from 'supertest';
import { createApp } from '../src/app.js';

const PARTICIPANTE = 'p-carla';
const OUTRO_PARTICIPANTE = 'p-diego';
const ORGANIZACAO = 'org-ana';

describe('PROBE - códigos recebidos', () => {
  let app: any;

  beforeEach(() => {
    app = createApp({ modoTeste: true });
  });

  afterEach(() => {
    app?.close?.();
  });

  async function resetar() {
    await request(app).post('/_teste/reset');
  }

  async function relogio(agora: string) {
    await request(app).put('/_teste/relogio').send({ agora });
  }

  async function criarAtividade(dados: any) {
    const res = await request(app).post('/atividades').set('X-Usuario', ORGANIZACAO).send(dados);
    return res.body;
  }

  async function inscrever(atividadeId: string, participante: string) {
    const res = await request(app).post(`/atividades/${atividadeId}/inscricoes`).set('X-Usuario', participante);
    return res.body;
  }

  it('probe', async () => {
    await resetar();

    const minicurso = await criarAtividade({
      titulo: 'Minicurso probe',
      tipo: 'minicurso',
      salaId: 'lab-3',
      vagas: 10,
      encontros: [
        { inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T22:00:00-03:00' },
        { inicio: '2026-10-20T19:00:00-03:00', fim: '2026-10-20T22:00:00-03:00' }
      ]
    });

    await relogio('2026-10-24T10:00:00-03:00');
    const semInscricao = await request(app).post(`/atividades/${minicurso.id}/certificado`).set('X-Usuario', PARTICIPANTE);

    const palestra = await criarAtividade({
      titulo: 'Palestra probe espera',
      tipo: 'palestra',
      salaId: 'sala-101',
      vagas: 1,
      encontros: [
        { inicio: '2026-10-19T10:00:00-03:00', fim: '2026-10-19T11:00:00-03:00' }
      ]
    });
    await inscrever(palestra.id, OUTRO_PARTICIPANTE);
    await inscrever(palestra.id, PARTICIPANTE);
    await relogio('2026-10-24T10:00:00-03:00');
    const emEspera = await request(app).post(`/atividades/${palestra.id}/certificado`).set('X-Usuario', PARTICIPANTE);

    const minicurso2 = await criarAtividade({
      titulo: 'Minicurso probe cancelada',
      tipo: 'minicurso',
      salaId: 'lab-2',
      vagas: 10,
      encontros: [
        { inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T22:00:00-03:00' },
        { inicio: '2026-10-20T19:00:00-03:00', fim: '2026-10-20T22:00:00-03:00' }
      ]
    });
    const insc = await inscrever(minicurso2.id, PARTICIPANTE);
    await request(app).post(`/inscricoes/${insc.id}/cancelamento`).set('X-Usuario', PARTICIPANTE);
    await relogio('2026-10-24T10:00:00-03:00');
    const cancelada = await request(app).post(`/atividades/${minicurso2.id}/certificado`).set('X-Usuario', PARTICIPANTE);

    await relogio('2026-10-20T21:00:00-03:00');
    const naoEncerrada = await request(app).post(`/atividades/${minicurso.id}/certificado`).set('X-Usuario', PARTICIPANTE);

    // eslint-disable-next-line no-console
    console.log(JSON.stringify({
      semInscricao: { status: semInscricao.status, erro: semInscricao.body.erro },
      emEspera: { status: emEspera.status, erro: emEspera.body.erro },
      cancelada: { status: cancelada.status, erro: cancelada.body.erro },
      naoEncerrada: { status: naoEncerrada.status, erro: naoEncerrada.body.erro }
    }));
    expect(true).toBe(true);
  });
});

